def compute(vars):
    costs_millions = vars["v1"]
    face_amount_billions = vars["v2"]
    face_amount_millions = face_amount_billions * 1000

    if face_amount_millions == 0:
        return {
            "value": None,
            "trace": {
                "costs_millions": costs_millions,
                "face_amount_billions": face_amount_billions,
                "face_amount_millions": face_amount_millions,
                "output_meta": {
                    "currency": None,
                    "scale": "ones",
                    "unit": "percentage"
                }
            }
        }

    percentage = (costs_millions / face_amount_millions) * 100

    return {
        "value": percentage,
        "trace": {
            "costs_millions": costs_millions,
            "face_amount_billions": face_amount_billions,
            "face_amount_millions": face_amount_millions,
            "ratio": costs_millions / face_amount_millions,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
